  ('mace-and-chain-nb', 'Mace and Chain', 'nightbane', 'weapon', 4.5, 280, NULL, '2-12', 0, NULL, NULL, NULL, NULL, NULL, 'Ball and chain, ancient weapons table, printed 205. One-handed. Average length .9m/3.0ft.', 'Nightbane RPG p.205'),
  ('nunchaku-nb', 'Nunchaku', 'nightbane', 'weapon', 2.5, 30, NULL, '1-8', 0, NULL, NULL, NULL, NULL, NULL, 'Ball and chain, ancient weapons table, printed 205. Two-handed. Average length .8m/2.75ft. Also described on printed 207 (usually called Numchuks): can be used as a paired weapon for striking, and can entangle only if one weapon is used with two hands. That entry prices it at $30 each, 1D8 - the same as this table row, so it is one row.', 'Nightbane RPG p.205'),
  ('arab-mace-nb', 'Arab Mace', 'nightbane', 'weapon', 3, 240, NULL, '1-8', 0, NULL, NULL, NULL, NULL, NULL, 'Blunt weapons, ancient weapons table, printed 205. One-handed. Average length .6m/2.0ft.', 'Nightbane RPG p.205'),
